SELECT sm.id, fm.data_set_id, fm.id AS file_id, fm.original_name AS file_name, sm.layer_key, sm.extent_kind, ST_AsGeoJSON(ST_ForcePolygonCCW(
ST_SimplifyPreserveTopology(sm.geographic_extent, #{tolerance}) sm.geographic_extent
), 15, 0) AS geo_json FROM ocean_gis.gis_file_spatial_metadata sm JOIN ocean_gis.gis_file_meta fm ON fm.id = sm.file_meta_id WHERE fm.deleted = 0 AND fm.upload_status = 'READY' AND fm.metadata_status = 'COMPLETED' AND fm.data_set_id IN #{id} ORDER BY fm.data_set_id, fm.id, sm.layer_key

SELECT id FROM ocean_gis.gis_file_meta
WHERE 
ORDER BY create_time, id LIMIT #{limit}

mapper.update:
UPDATE ocean_gis.gis_file_meta
SET metadata_lease_expires_at = #{leaseExpiresAt}
WHERE id = #{id} AND metadata_version = #{version}
  AND metadata_status = 'RUNNING' AND deleted = 0 AND upload_status = 'READY'
  AND metadata_lease_expires_at > CURRENT_TIMESTAMP
